import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const MySales = () => {
  const userId = sessionStorage.getItem("userId");
  const [sales, setSales] = useState([]);
  const [payoutTotal, setPayoutTotal] = useState(0);

  useEffect(() => {
    const fetchSales = async () => {
      const res = await fetch(`${API_BASE_URL}/api/seller-orders/${userId}`);
      const data = await res.json();
      setSales(data);
      const total = data.reduce((sum, sale) => sum + parseFloat(sale.price || 0), 0);
      setPayoutTotal(total);
    };
    fetchSales();
  }, [userId]);

  const handlePayout = () => {
    const fee = payoutTotal * 0.05;
    const payout = payoutTotal - fee;
    alert(`💰 Paid out $${payout.toFixed(2)} (5% fee: $${fee.toFixed(2)})`);
    setPayoutTotal(0); // Simulated reset
  };

  return (
    <div className="page-container">
      <Navbar />
      <div className="main-content my-sales-page">
        <h2>My Sales</h2>
        {sales.length === 0 ? (
          <p>You have no sales yet.</p>
        ) : (
          <>
            {sales.map((sale, i) => (
              <div key={i} className="sale-item">
                <h3>{sale.title}</h3>
                <p>Sold for: ${sale.price}</p>
                <p>Buyer: {sale.buyer_name}</p>
              </div>
            ))}
            <div className="sales-summary">
              <p>Total Earnings: ${payoutTotal.toFixed(2)}</p>
              <button onClick={handlePayout} className="payout-btn">Payout Now</button>
            </div>
          </>
        )}
      </div>
      <Footer />
    </div>
  );
};

export default MySales;
